#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/swift/tasks/setup-deps-swift.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Resolve the SwiftPM and Xcode package dependencies from Package.resolved; --upgrade resolves them again to the newest allowed versions"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--upgrade" help="update Package.resolved to the newest versions that the manifests allow"

import glob
import os
import shutil
import subprocess
import sys
import tempfile

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def succeeds(*command):
  """Whether the system command runs and exits 0. It prints nothing."""
  try:
    result = subprocess.run(command, check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
  except OSError:
    return False
  return result.returncode == 0


def run(*command):
  """Run the system command. A failure stops the task with its code."""
  result = subprocess.run(command, check=False)
  if result.returncode != 0:
    sys.exit(result.returncode)


# Shipped with the swift tool. It acts on the repository root only: the iOS
# part of a Flutter app belongs to setup:deps:20-flutter. Without Package.swift
# and without an *.xcodeproj, the task does not apply and prints nothing.
os.chdir(os.environ["MISE_PROJECT_ROOT"])

has_package = os.path.isfile("Package.swift")
projects = [p for p in sorted(glob.glob("*.xcodeproj")) if os.path.isdir(p)]

if not has_package and not projects:
  sys.exit(0)

upgrade = os.environ.get("usage_upgrade") == "true"
if upgrade:
  helpers.print_header("Upgrading Swift dependencies ...")
else:
  helpers.print_header("Installing Swift dependencies ...")

# On a host that is not macOS, the task skips, so setup on a Linux CI host
# continues.
if os.uname().sysname != "Darwin":
  helpers.print_warn("Swift dependencies are macOS only, skipped")
  sys.exit(0)

if len(projects) > 1:
  helpers.print_error(f"The root has more than one *.xcodeproj: {' '.join(projects)}. Keep one.")
  sys.exit(1)

# swift and xcodebuild come from the developer folder that xcode-select
# selects, not from mise. An *.xcodeproj needs a full Xcode: with only the
# Command Line Tools, xcodebuild fails. A SwiftPM-only root needs only swift,
# which the Command Line Tools supply.
if projects:
  if not succeeds("xcodebuild", "-version"):
    helpers.print_error("Xcode is not selected. Run: sudo xcode-select -s /Applications/Xcode.app")
    sys.exit(1)
elif not succeeds("swift", "--version"):
  helpers.print_error("swift is not available. Install the Command Line Tools: xcode-select --install")
  sys.exit(1)

if has_package:
  if upgrade:
    helpers.print_subheader("Updating the SwiftPM packages ...")
    run("swift", "package", "update")
  else:
    helpers.print_subheader("Resolving the SwiftPM packages ...")
    # Package.resolved decides the versions; a resolve never changes them.
    run("swift", "package", "resolve", "--force-resolved-versions")

if len(projects) == 1:
  project = projects[0]
  resolved = f"{project}/project.xcworkspace/xcshareddata/swiftpm/Package.resolved"
  if upgrade:
    helpers.print_subheader("Updating the Xcode project packages ...")
    # Without Package.resolved, xcodebuild resolves every package again. If
    # the resolve fails, the old file goes back.
    backup = ""
    if os.path.isfile(resolved):
      handle, backup = tempfile.mkstemp()
      os.close(handle)
      shutil.copy(resolved, backup)
      os.remove(resolved)
    code = None
    try:
      code = subprocess.run(
        [
          "xcodebuild",
          "-resolvePackageDependencies",
          "-project",
          project,
          "-clonedSourcePackagesDirPath",
          ".build/SourcePackages",
        ],
        check=False,
      ).returncode
    finally:
      if backup:
        if code != 0:
          shutil.copy(backup, resolved)
        os.remove(backup)
    if code != 0:
      sys.exit(code)
  else:
    helpers.print_subheader("Resolving the Xcode project packages ...")
    run(
      "xcodebuild",
      "-resolvePackageDependencies",
      "-project",
      project,
      "-clonedSourcePackagesDirPath",
      ".build/SourcePackages",
      "-onlyUsePackageVersionsFromResolvedFile",
    )
